            nn3=sum(1 for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc) and 0<=r+dr<H and 0<=c+dc<W and I[r+dr][c+dc]==3)
            if nn==n and nn3==nb3: hits.append(((r,c),'paint' if O[r][c]==1 else 'keep'))
    print(hits)

from collections import deque
for name in ['Demo pair 1','Demo pair 2']:
    I=G[name+' input']; O=G[name+' output']
    H=len(I);W=len(I[0])
    S={(r,c) for r in range(H) for c in range(W) if I[r][c]==2}
    # 8-connected components of {0,3}: does painting = components containing a seed, fully?
    seen=[[False]*W for _ in range(H)]; bad=0; desc=[]
    for r in range(H):
        for c in range(W):
            if I[r][c] in (0,3) and not seen[r][c]:
                q=deque([(r,c)]); cells=[]; seen[r][c]=True
                while q:
                    rr,cc=q.popleft(); cells.append((rr,cc))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=rr+dr,cc+dc
                            if 0<=nr<H and 0<=nc<W and I[nr][nc] in (0,3) and not seen[nr][nc]:
                                seen[nr][nc]=True; q.append((nr,nc))
                hasseed=any(abs(r-sr)<=1 and abs(c-sc)<=1 for r,c in cells for sr,sc in S)
                actual=set(O[r][c] for r,c in cells)
                if hasseed and 1 not in actual: bad+=1; desc.append(('no1',cells[:4]))
                if not hasseed and 1 in actual: bad+=1; desc.append(('paintnoseed',cells[:4]))
    print(name,'mismatch:',bad,desc[:6])
